select
  id, study_id, patient_id, exam_no, test_no, create_time, update_time, result_time, dental_caries, periodontal_disease, oral_mucosal_disease, oral_maxillofacial_surgery, oral_restoration, orthodontics
from td_oral


        and id = #{id}


        and study_id = #{studyId}


        and patient_id = #{patientId}


        and exam_no = #{examNo}


        and test_no = #{testNo}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and result_time = #{resultTime}


        and dental_caries = #{dentalCaries}


        and periodontal_disease = #{periodontalDisease}


        and oral_mucosal_disease = #{oralMucosalDisease}


        and oral_maxillofacial_surgery = #{oralMaxillofacialSurgery}


        and oral_restoration = #{oralRestoration}


        and orthodontics = #{orthodontics}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from td_oral


        and id = #{id}


        and study_id = #{studyId}


